def run_once(cfg, db, dry_run=False):
    fresh = []
    for feed_cfg in cfg["feeds"]:
        try:
            items = feeds.fetch(feed_cfg)
        except feeds.FeedError as exc:
            print(f"warn: feed {feed_cfg['name']} failed: {exc}", file=sys.stderr)
            continue
        fresh.extend(
            i for i in items if not store.is_sent(db, feed_cfg["name"], i["link"])
        )

    fresh.sort(key=lambda i: i.get("published", ""), reverse=True)

    sent = 0
    sent_by_source = {}
    for chan_cfg in cfg["channels"]:
        selected = [i for i in fresh if matches(i, chan_cfg)]
        if not selected:
            continue
        body = render.digest(selected, chan_cfg)
        if dry_run:
            print(f"--- would send to {chan_cfg['name']} ---")
            print(body)
            sent += len(selected)
            continue
        channels.send(chan_cfg, body)
        sent += len(selected)
        for i in selected:
            sent_by_source.setdefault(i["source"], []).append(i)

    for source, items in sent_by_source.items():
        store.mark_sent(db, source, items)

    return sent

